-- Arbeitsrecht Berufsbildung > Betriebswirtschaftliche Grundlagen > Gewinnermittlung > GuV (Gewinn- Verlustrechnung)
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Wird in der GuV eines IT-Betriebs der Gewinn durch Umsatzerlöse minus Aufwendungen ermittelt?', 2, '[{"text": "Ja", "correct": true, "because": "Die GuV zeigt Erlöse minus Aufwendungen"}, {"text": "Nein", "correct": false, "because": "Das ist die Grundlage der GuV"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Abschreibungen auf IT-Ausrüstung in der GuV eines IT-Betriebs berücksichtigt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Abschreibungen sind Aufwendungen in der GuV"}, {"text": "Nein", "correct": false, "because": "Abschreibungen sind Teil der GuV"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein IT-Betrieb mit der GuV den Verlust eines Geschäftsjahres darstellen?', 2, '[{"text": "Ja", "correct": true, "because": "Die GuV zeigt Gewinn oder Verlust"}, {"text": "Nein", "correct": false, "because": "Verlust wird in der GuV ausgewiesen"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind in der GuV eines IT-Betriebs nur die tatsächlich eingegangenen Einnahmen relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Die GuV basiert auf dem Ist-Prinzip, nicht nur auf Zuflüssen"}, {"text": "Ja", "correct": false, "because": "EÜR berücksichtigt Zuflüsse, GuV nicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss ein IT-Betrieb bei der GuV die Bilanz mit einbeziehen?', 2, '[{"text": "Nein", "correct": true, "because": "GuV ist eigenständig, Bilanz separat"}, {"text": "Ja", "correct": false, "because": "GuV und Bilanz sind getrennt"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel der GuV für einen IT-Betrieb?', 2, '[{"text": "Darstellung des Gewinns oder Verlusts", "correct": true, "because": "GuV zeigt das Ergebnis eines Geschäftsjahres"}, {"text": "Darstellung von Vermögen", "correct": false, "because": "Das ist die Bilanz"}, {"text": "Steuererhöhung", "correct": false, "because": "Nicht das Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kosten werden in der GuV eines IT-Betriebs als Aufwendungen ausgewiesen?', 3, '[{"text": "Abschreibungen auf Server", "correct": true, "because": "Abschreibungen sind Aufwendungen"}, {"text": "Einnahmen aus Projekten", "correct": false, "because": "Das sind Erlöse"}, {"text": "Eigenkapital", "correct": false, "because": "Das ist eine Bilanzposition"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Unternehmensform muss typischerweise eine GuV erstellen?', 3, '[{"text": "GmbH", "correct": true, "because": "Kapitalgesellschaften sind bilanzierungspflichtig"}, {"text": "Einzelunternehmer", "correct": false, "because": "Einzelunternehmer nutzen oft die EÜR"}, {"text": "Freiberufler", "correct": false, "because": "Freiberufler nutzen oft die EÜR"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Gesetz regelt die Erstellung der GuV für einen IT-Betrieb?', 2, '[{"text": "Handelsgesetzbuch (HGB)", "correct": true, "because": "HGB legt GuV-Regeln fest"}, {"text": "BBiG", "correct": false, "because": "BBiG regelt Ausbildung"}, {"text": "NachwG", "correct": false, "because": "NachwG regelt Nachweise"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert, wenn ein IT-Betrieb in der GuV falsche Aufwendungen angibt?', 3, '[{"text": "Der Gewinn wird falsch dargestellt", "correct": true, "because": "Fehler beeinflussen das Ergebnis"}, {"text": "Keine Auswirkungen", "correct": false, "because": "Fehler haben Konsequenzen"}, {"text": "Die Bilanz bleibt korrekt", "correct": false, "because": "GuV-Fehler wirken sich auf die Bilanz aus"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Positionen werden in der GuV eines IT-Betriebs als Erlöse ausgewiesen?', 4, '[{"text": "Umsatzerlöse aus Projekten", "correct": true, "because": "Projekterlöse sind Erlöse"}, {"text": "Einnahmen aus Lizenzverkäufen", "correct": true, "because": "Lizenzverkäufe sind Erlöse"}, {"text": "Abschreibungen auf Hardware", "correct": false, "because": "Das sind Aufwendungen"}, {"text": "Zinsen aus Bankguthaben", "correct": true, "because": "Zinsen sind Erträge"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufwendungen werden in der GuV eines IT-Betriebs berücksichtigt?', 3, '[{"text": "Materialkosten für Projekte", "correct": true, "because": "Materialkosten sind Aufwendungen"}, {"text": "Abschreibungen auf Server", "correct": true, "because": "Abschreibungen sind Aufwendungen"}, {"text": "Umsatzerlöse", "correct": false, "because": "Das sind Erlöse"}, {"text": "Personalkosten für Fachinformatiker", "correct": true, "because": "Personalkosten sind Aufwendungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aussagen treffen auf die GuV eines IT-Betriebs zu?', 4, '[{"text": "Zeigt den Gewinn oder Verlust", "correct": true, "because": "Hauptziel der GuV"}, {"text": "Berücksichtigt Abschreibungen", "correct": true, "because": "Abschreibungen sind Aufwendungen"}, {"text": "Basiert auf dem Zuflussprinzip", "correct": false, "because": "Das gilt für die EÜR"}, {"text": "Dient der Steuerermittlung", "correct": true, "because": "GuV ist Grundlage für Steuern"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kosten beeinflussen den Gewinn in der GuV eines IT-Betriebs?', 3, '[{"text": "Personalkosten", "correct": true, "because": "Aufwendungen mindern den Gewinn"}, {"text": "Materialkosten", "correct": true, "because": "Aufwendungen mindern den Gewinn"}, {"text": "Eigenkapital", "correct": false, "because": "Bilanzposition, kein Aufwand"}, {"text": "Abschreibungen", "correct": true, "because": "Aufwendungen mindern den Gewinn"}]'),
('00000000-0000-0000-0000-000000000000', 'Was unterscheidet die GuV von der EÜR für einen IT-Betrieb?', 3, '[{"text": "GuV berücksichtigt Abschreibungen", "correct": true, "because": "EÜR tut dies nicht"}, {"text": "EÜR basiert auf Zuflüssen", "correct": true, "because": "GuV auf Ist-Werten"}, {"text": "GuV ist für Einzelunternehmer", "correct": false, "because": "GuV für bilanzierungspflichtige Unternehmen"}, {"text": "EÜR zeigt Vermögen", "correct": false, "because": "Vermögen zeigt die Bilanz"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Die GuV zeigt den Gewinn eines IT-Betriebs. b) Abschreibungen werden in der GuV nicht berücksichtigt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gewinn ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Materialkosten sind Aufwendungen in der GuV eines IT-Betriebs. b) Die GuV basiert auf dem Zuflussprinzip.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Materialkosten ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die GuV eines IT-Betriebs zeigt den Verlust, wenn Aufwendungen die Erlöse übersteigen. b) Eigenkapital wird in der GuV ausgewiesen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Verlust ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Personalkosten mindern den Gewinn in der GuV. b) Die GuV ist für Einzelunternehmer freiwillig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Personalkosten ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die GuV eines IT-Betriebs berücksichtigt Umsatzerlöse. b) Die GuV zeigt den finanziellen Zustand zum Stichtag.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Erlöse ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

